starter_code:
function tranche(liste, page, taille) {
  return liste.slice(page, page + taille);
}

solution:
function tranche(liste, page, taille) {
  return liste.slice((page - 1) * taille, page * taille);
}

starter_code:
function borner(texte, defaut, min, max) {
  return Number(texte);
}

solution:
function borner(texte, defaut, min, max) {
  const n = Number.parseInt(texte, 10);
  return Math.min(Math.max(Number.isNaN(n) ? defaut : n, min), max);
}

starter_code:
function trier(liste, tri) {
  return liste.sort((a, b) => a[tri] > b[tri] ? 1 : -1);
}

solution:
function trier(liste, tri) {
  return [...liste].sort((a, b) => tri === "prix" ? a.prix - b.prix : a.nom.localeCompare(b.nom, "fr"));
}

starter_code:
function paginer(liste, options) {
  return { page: 1, pages: 1, total: liste.length, produits: liste };
}

solution:
function paginer(liste, options) {
  const tri = options.tri === "prix" ? "prix" : "nom";
  const t = Number.parseInt(options.taille, 10);
  const taille = Math.min(Math.max(Number.isNaN(t) ? 10 : t, 1), 50);
  const triee = [...liste].sort((a, b) => tri === "prix" ? a.prix - b.prix : a.nom.localeCompare(b.nom, "fr"));
  const pages = Math.max(1, Math.ceil(triee.length / taille));
  const n = Number.parseInt(options.page, 10);
  const page = Math.min(Math.max(Number.isNaN(n) ? 1 : n, 1), pages);
  return { page, pages, total: triee.length, produits: triee.slice((page - 1) * taille, page * taille) };
}
